-- نص «الخصوصية والاستخدام» بالعربية الفصحى وبكلام مفهوم (طلب المالك ٢٠٢٦-١٠-٢٨)، والإنجليزي مطابق له.
update public.app_config set value = $j${"title": "الخصوصية والاستخدام", "subtitle": "سياسة الخصوصية وشروط الاستخدام", "updated": "2026-10-28", "sections": [{"key": "privacy", "title": "بياناتك وخصوصيتك", "items": [{"id": "collect", "title": "ما نجمعه", "lines": ["نجمع اسمك ورقم هاتفك فقط.", "تُدخل رقم هاتفك بنفسك لتسجيل الدخول، فنربطه باسمك ونحفظه على خوادمنا.", "ونحفظ ما تختار إضافته من معلومات، مثل بريدك الإلكتروني وصلة قرابتك وتاريخ ميلادك وصورتك ونبذتك ومنشوراتك."]}, {"id": "relatives", "title": "بيانات أقاربك", "lines": ["عندما تضيف أحد أقاربك، نحفظ ما تُدخله عنه من اسم وتواريخ وصورة، ويظهر ذلك لأعضاء العائلة في الشجرة.", "يُرجى إضافة هذه البيانات بعلم أصحابها، ويمكنك تعديلها أو حذفها في أي وقت."]}, {"id": "auto", "title": "ما يُجمع تلقائياً", "lines": ["نوع جهازك وآخر نشاط لك وأخطاء التطبيق، وذلك لحماية حسابك وتحسين التطبيق."]}, {"id": "why", "title": "لماذا نجمعها", "lines": ["لتشغيل الشجرة والأخبار والإشعارات فقط؛ فلا نعرض إعلانات ولا نبيع بياناتك."]}, {"id": "who", "title": "من يطّلع عليها", "lines": ["أعضاء العائلة المسجّلون في التطبيق فقط، ويمكنك إخفاء رقم هاتفك عنهم."]}, {"id": "share", "title": "مع من نشاركها", "lines": ["لا نشاركها مع أي جهة لأغراض تجارية.", "نستعين فقط بمزوّدي الخدمات اللازمة لتشغيل التطبيق: الاستضافة، والرسائل النصية، وإشعارات Apple وGoogle."]}, {"id": "otp", "title": "رمز الدخول", "lines": ["يصلك رمز الدخول برسالة نصية، ولا يصلح إلا لمرة واحدة.", "ولحماية حسابك نراجع محاولات الدخول المتكررة."]}, {"id": "security", "title": "حماية بياناتك", "lines": ["تنتقل بياناتك عبر اتصال مشفّر، وتُحفظ على خوادم Supabase."]}, {"id": "delete", "title": "حذف حسابك", "lines": ["يمكنك حذف حسابك من الإعدادات في أي وقت، فيُحذف فوراً مع صورك وبياناتك الشخصية ومنشوراتك وتعليقاتك.", "ويبقى اسمك وموقعك في شجرة العائلة حفاظاً على تسلسل النسب."]}]}, {"key": "terms", "title": "قواعد الاستخدام", "items": [{"id": "eligibility", "title": "لمن التطبيق", "lines": ["التطبيق مخصّص لأبناء عائلة المحمدعلي وأقاربهم."]}, {"id": "account", "title": "حسابك", "lines": ["حسابك شخصي، فلا تُطلع أحداً على رمز الدخول."]}, {"id": "respect", "title": "لا تهاون مع الإساءة", "lines": ["يُمنع نشر أي محتوى مسيء، أو انتحال شخصية غيرك، أو نشر بيانات الأعضاء خارج التطبيق.", "يمكنك الإبلاغ عن أي محتوى أو عضو وحظره، ونراجع كل بلاغ خلال ٢٤ ساعة، فنحذف المحتوى المخالف وقد نوقف حساب صاحبه."]}, {"id": "content", "title": "ما تنشره", "lines": ["ما تنشره ملكٌ لك، ويحق لنا إخفاؤه أو حذفه إذا خالف هذه القواعد."]}, {"id": "contact", "title": "التواصل معنا", "lines": ["من خلال «التواصل» داخل التطبيق، أو عبر البريد الإلكتروني info@almohali.com"]}]}]}$j$::jsonb, default_value = $j${"title": "الخصوصية والاستخدام", "subtitle": "سياسة الخصوصية وشروط الاستخدام", "updated": "2026-10-28", "sections": [{"key": "privacy", "title": "بياناتك وخصوصيتك", "items": [{"id": "collect", "title": "ما نجمعه", "lines": ["نجمع اسمك ورقم هاتفك فقط.", "تُدخل رقم هاتفك بنفسك لتسجيل الدخول، فنربطه باسمك ونحفظه على خوادمنا.", "ونحفظ ما تختار إضافته من معلومات، مثل بريدك الإلكتروني وصلة قرابتك وتاريخ ميلادك وصورتك ونبذتك ومنشوراتك."]}, {"id": "relatives", "title": "بيانات أقاربك", "lines": ["عندما تضيف أحد أقاربك، نحفظ ما تُدخله عنه من اسم وتواريخ وصورة، ويظهر ذلك لأعضاء العائلة في الشجرة.", "يُرجى إضافة هذه البيانات بعلم أصحابها، ويمكنك تعديلها أو حذفها في أي وقت."]}, {"id": "auto", "title": "ما يُجمع تلقائياً", "lines": ["نوع جهازك وآخر نشاط لك وأخطاء التطبيق، وذلك لحماية حسابك وتحسين التطبيق."]}, {"id": "why", "title": "لماذا نجمعها", "lines": ["لتشغيل الشجرة والأخبار والإشعارات فقط؛ فلا نعرض إعلانات ولا نبيع بياناتك."]}, {"id": "who", "title": "من يطّلع عليها", "lines": ["أعضاء العائلة المسجّلون في التطبيق فقط، ويمكنك إخفاء رقم هاتفك عنهم."]}, {"id": "share", "title": "مع من نشاركها", "lines": ["لا نشاركها مع أي جهة لأغراض تجارية.", "نستعين فقط بمزوّدي الخدمات اللازمة لتشغيل التطبيق: الاستضافة، والرسائل النصية، وإشعارات Apple وGoogle."]}, {"id": "otp", "title": "رمز الدخول", "lines": ["يصلك رمز الدخول برسالة نصية، ولا يصلح إلا لمرة واحدة.", "ولحماية حسابك نراجع محاولات الدخول المتكررة."]}, {"id": "security", "title": "حماية بياناتك", "lines": ["تنتقل بياناتك عبر اتصال مشفّر، وتُحفظ على خوادم Supabase."]}, {"id": "delete", "title": "حذف حسابك", "lines": ["يمكنك حذف حسابك من الإعدادات في أي وقت، فيُحذف فوراً مع صورك وبياناتك الشخصية ومنشوراتك وتعليقاتك.", "ويبقى اسمك وموقعك في شجرة العائلة حفاظاً على تسلسل النسب."]}]}, {"key": "terms", "title": "قواعد الاستخدام", "items": [{"id": "eligibility", "title": "لمن التطبيق", "lines": ["التطبيق مخصّص لأبناء عائلة المحمدعلي وأقاربهم."]}, {"id": "account", "title": "حسابك", "lines": ["حسابك شخصي، فلا تُطلع أحداً على رمز الدخول."]}, {"id": "respect", "title": "لا تهاون مع الإساءة", "lines": ["يُمنع نشر أي محتوى مسيء، أو انتحال شخصية غيرك، أو نشر بيانات الأعضاء خارج التطبيق.", "يمكنك الإبلاغ عن أي محتوى أو عضو وحظره، ونراجع كل بلاغ خلال ٢٤ ساعة، فنحذف المحتوى المخالف وقد نوقف حساب صاحبه."]}, {"id": "content", "title": "ما تنشره", "lines": ["ما تنشره ملكٌ لك، ويحق لنا إخفاؤه أو حذفه إذا خالف هذه القواعد."]}, {"id": "contact", "title": "التواصل معنا", "lines": ["من خلال «التواصل» داخل التطبيق، أو عبر البريد الإلكتروني info@almohali.com"]}]}]}$j$::jsonb where key = 'legal_content';
update public.app_config set value = $j${"title": "Privacy & Use", "subtitle": "Privacy Policy and Terms of Use", "updated": "2026-10-28", "sections": [{"key": "privacy", "title": "Your data and privacy", "items": [{"id": "collect", "title": "What we collect", "lines": ["We collect only your name and phone number.", "You enter your phone number yourself to sign in; we link it to your name and keep it on our servers.", "We also keep any information you choose to add, such as your email, family relationship, birth date, photo, bio and posts."]}, {"id": "relatives", "title": "Your relatives' details", "lines": ["When you add a relative, we keep the name, dates and photo you enter for them, and these appear to family members in the tree.", "Please add these details with the person's knowledge; you can edit or delete them at any time."]}, {"id": "auto", "title": "Collected automatically", "lines": ["Your device type, your latest activity and app errors, to protect your account and improve the app."]}, {"id": "why", "title": "Why we collect it", "lines": ["Only to run the tree, news and notifications; we show no ads and never sell your data."]}, {"id": "who", "title": "Who can see it", "lines": ["Only family members registered in the app, and you can hide your phone number from them."]}, {"id": "share", "title": "Who we share it with", "lines": ["We share it with no one for commercial purposes.", "We only use the service providers needed to run the app: hosting, text messages, and Apple and Google notifications."]}, {"id": "otp", "title": "Sign-in code", "lines": ["Your sign-in code arrives by text message and works only once.", "To protect your account, we review repeated sign-in attempts."]}, {"id": "security", "title": "Protecting your data", "lines": ["Your data travels over an encrypted connection and is stored on Supabase servers."]}, {"id": "delete", "title": "Deleting your account", "lines": ["You can delete your account from Settings at any time; it is deleted immediately along with your photos, personal details, posts and comments.", "Your name and place in the family tree remain, to keep the lineage intact."]}]}, {"key": "terms", "title": "Rules of use", "items": [{"id": "eligibility", "title": "Who the app is for", "lines": ["The app is for members of the Al-Mohammad Ali family and their relatives."]}, {"id": "account", "title": "Your account", "lines": ["Your account is personal, so never share your sign-in code with anyone."]}, {"id": "respect", "title": "Zero tolerance for abuse", "lines": ["Posting objectionable content, impersonating others, or sharing members' details outside the app is not allowed.", "You can report or block any content or member; we review every report within 24 hours, remove violating content, and may suspend the author's account."]}, {"id": "content", "title": "What you post", "lines": ["What you post belongs to you, and we may hide or remove it if it breaks these rules."]}, {"id": "contact", "title": "Contact us", "lines": ["Through «Contact» in the app, or by email at info@almohali.com"]}]}]}$j$::jsonb, default_value = $j${"title": "Privacy & Use", "subtitle": "Privacy Policy and Terms of Use", "updated": "2026-10-28", "sections": [{"key": "privacy", "title": "Your data and privacy", "items": [{"id": "collect", "title": "What we collect", "lines": ["We collect only your name and phone number.", "You enter your phone number yourself to sign in; we link it to your name and keep it on our servers.", "We also keep any information you choose to add, such as your email, family relationship, birth date, photo, bio and posts."]}, {"id": "relatives", "title": "Your relatives' details", "lines": ["When you add a relative, we keep the name, dates and photo you enter for them, and these appear to family members in the tree.", "Please add these details with the person's knowledge; you can edit or delete them at any time."]}, {"id": "auto", "title": "Collected automatically", "lines": ["Your device type, your latest activity and app errors, to protect your account and improve the app."]}, {"id": "why", "title": "Why we collect it", "lines": ["Only to run the tree, news and notifications; we show no ads and never sell your data."]}, {"id": "who", "title": "Who can see it", "lines": ["Only family members registered in the app, and you can hide your phone number from them."]}, {"id": "share", "title": "Who we share it with", "lines": ["We share it with no one for commercial purposes.", "We only use the service providers needed to run the app: hosting, text messages, and Apple and Google notifications."]}, {"id": "otp", "title": "Sign-in code", "lines": ["Your sign-in code arrives by text message and works only once.", "To protect your account, we review repeated sign-in attempts."]}, {"id": "security", "title": "Protecting your data", "lines": ["Your data travels over an encrypted connection and is stored on Supabase servers."]}, {"id": "delete", "title": "Deleting your account", "lines": ["You can delete your account from Settings at any time; it is deleted immediately along with your photos, personal details, posts and comments.", "Your name and place in the family tree remain, to keep the lineage intact."]}]}, {"key": "terms", "title": "Rules of use", "items": [{"id": "eligibility", "title": "Who the app is for", "lines": ["The app is for members of the Al-Mohammad Ali family and their relatives."]}, {"id": "account", "title": "Your account", "lines": ["Your account is personal, so never share your sign-in code with anyone."]}, {"id": "respect", "title": "Zero tolerance for abuse", "lines": ["Posting objectionable content, impersonating others, or sharing members' details outside the app is not allowed.", "You can report or block any content or member; we review every report within 24 hours, remove violating content, and may suspend the author's account."]}, {"id": "content", "title": "What you post", "lines": ["What you post belongs to you, and we may hide or remove it if it breaks these rules."]}, {"id": "contact", "title": "Contact us", "lines": ["Through «Contact» in the app, or by email at info@almohali.com"]}]}]}$j$::jsonb where key = 'legal_content_en';
